@@ -9,4 +9,13 @@ public sealed class Outbox
 {
     private const int BatchSize = 50;

+    /// <summary>Sends the queued messages in batches of 20.</summary>
+    public async Task FlushAsync(CancellationToken ct)
+    {
+        foreach (var batch in _queue.Chunk(BatchSize))
+        {
+            await _transport.SendAsync(batch, ct);
+        }
+    }
+
     public int Pending => _queue.Count;
